//! Raw FFI bindings to the [audio.cpp](https://github.com/0xShug0/audio.cpp)
//! C ABI, `include/audiocpp.h`.
//!
//! These are generated by `scripts/gen-bindings.sh` and mirror the header 1:1.
//! See the `audio-cpp` crate for a safe wrapper, and upstream `docs/c_api.md`
//! for the contract (borrowed outputs, thread-local errors, lifetimes).

#![no_std]
#![allow(non_camel_case_types, non_upper_case_globals, non_snake_case)]

include!("bindings.rs");

/// `audiocpp_abi_version()` value of the header these bindings were generated
/// from, packed as `(major << 16) | (minor << 8) | patch`.
pub const AUDIOCPP_ABI_VERSION: u32 =
    (AUDIOCPP_ABI_VERSION_MAJOR << 16) | (AUDIOCPP_ABI_VERSION_MINOR << 8) | AUDIOCPP_ABI_VERSION_PATCH;
